self.onmessage = function(event) {
  const data = event.data;
  const headers = data.headers;
  const rows = data.rows;
  const delimiter = data.delimiter || ',';

  // Generate CSV content
  let csvContent = headers.join(delimiter) + '\n';

  // Process rows in chunks to avoid freezing the browser
  const chunkSize = 10000;
  const totalRows = rows.length;
  let processedRows = 0;

  for (let i = 0; i < totalRows; i += chunkSize) {
    const chunk = rows.slice(i, i + chunkSize);
    const chunkCsv = chunk.map(row => row.join(delimiter)).join('\n');
    csvContent += chunkCsv + '\n';
    processedRows += chunk.length;

    // Simulate a small delay to prevent the browser from freezing
    if (i % (chunkSize * 10) === 0) {
      self.postMessage({ progress: (processedRows / totalRows) * 100 });
    }
